/**
 * Public door catalog.
 * State and county shapes live in src/geo, generated by scripts/build-maps.mjs.
 * COUNTIES is the live override list. Walton is the only live county.
 * A county with live: false gets a coming soon page and a request form.
 * A live county also needs href, the taxes-host path of its budget pages.
 */
import { COUNTY_MAPS, STATE_MAP } from "./geo/registry";
import type { CountyKind } from "./geo/types";

export interface UsState {
  fips: string;
  abbr: string;
  name: string;
  slug: string;
}

export interface CountyPlace {
  stateSlug: string;
  slug: string;
  name: string;
  live: boolean;
  href?: string;
  kind?: CountyKind;
}

export const COUNTIES: CountyPlace[] = [
  { stateSlug: "florida", slug: "walton", name: "Walton County", live: true, href: "/walton" },
];

export const US_STATES: UsState[] = STATE_MAP.states
  .map(({ fips, abbr, name, slug }) => ({ fips, abbr, name, slug }))
  .sort((a, b) => a.name.localeCompare(b.name));

export const LIVE_STATE_SLUG = COUNTIES.find((county) => county.live)?.stateSlug ?? "";

export function stateBySlug(slug: string): UsState | undefined {
  return US_STATES.find((state) => state.slug === slug);
}

export function isLiveState(state: UsState): boolean {
  return COUNTIES.some((county) => county.live && county.stateSlug === state.slug);
}

export function countiesIn(stateSlug: string): CountyPlace[] {
  const shapes = COUNTY_MAPS[stateSlug]?.counties ?? [];
  const known = new Set(shapes.map((shape) => shape.slug));
  const fromMap: CountyPlace[] = shapes.map((shape) => {
    const override = COUNTIES.find((county) => county.stateSlug === stateSlug && county.slug === shape.slug);
    if (override) return { kind: shape.kind, ...override };
    return { stateSlug, slug: shape.slug, name: shape.name, live: false, kind: shape.kind };
  });
  const extras = COUNTIES.filter((county) => county.stateSlug === stateSlug && !known.has(county.slug));
  return fromMap.concat(extras).sort((a, b) => a.name.localeCompare(b.name) || a.slug.localeCompare(b.slug));
}

export function countyByPath(stateSlug: string, countySlug: string): CountyPlace | undefined {
  return countiesIn(stateSlug).find((county) => county.slug === countySlug);
}

export function countyHref(county: CountyPlace): string {
  if (county.live && county.href) return county.href;
  return `/${county.stateSlug}/${county.slug}`;
}

export function liveCounties(): CountyPlace[] {
  return COUNTIES.filter((county) => county.live);
}

export function countyChoices(stateSlug: string): { slug: string; name: string; live: boolean }[] {
  return countiesIn(stateSlug).map((county) => ({ slug: county.slug, name: county.name, live: county.live }));
}
